mapper.select:
SELECT * FROM (
    SELECT class_code, category_code, name, price, address, star_rating_avg, single_introduce
    FROM CLASS
    
        
            category_code = #{categoryCode}
        
    
    ORDER BY star_rating_avg DESC
) WHERE ROWNUM <= #{limitCount}

SELECT class_code, category_code, name, price, address, star_rating_avg, single_introduce FROM CLASS
category_code = #{categoryCode}
ORDER BY star_rating_avg DESC

SELECT DISTINCT c.class_code, c.category_code, c.name, c.price, c.address, c.star_rating_avg, c.single_introduce FROM CLASS c JOIN CLASS_REPEAT_RULE r ON c.class_code = r.class_code JOIN SCHEDULE s ON r.repeat_rule_code = s.repeat_rule_code
AND c.category_code = #{categoryCode}
AND TRUNC(s.class_date) = TRUNC(#{scheduleDTO.classDate})
AND s.start_time >= #{scheduleDTO.startTime}
AND s.sold_out_yn = 'N' AND s.remaining_people > 0
